from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()
        self.borrowed = {}  # book_id -> (user, due_date)
        self.user_books = {}  # user -> set of book_ids
        self.fines = {}  # user -> float

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self.borrowed:
            raise ValueError(f"Book {book_id} is already borrowed")
        if self.fines.get(user, 0.0) > 0 and self.user_books.get(user):
            raise ValueError(
                f"User {user} has unpaid fines and already holds a book"
            )
        due = day + timedelta(days=self.loan_days)
        self.borrowed[book_id] = (user, due)
        self.user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.borrowed:
            raise ValueError(f"Book {book_id} is not borrowed")
        holder, due = self.borrowed[book_id]
        if holder != user:
            raise ValueError(
                f"Book {book_id} is not borrowed by user {user}"
            )
        fine = self._compute_fine(due, day)
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine
        del self.borrowed[book_id]
        self.user_books[user].discard(book_id)
        if not self.user_books[user]:
            del self.user_books[user]
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self.fines.pop(user, None)

    def _compute_fine(self, due: date, returned: date) -> float:
        # Count business days strictly after `due` and up to `returned`.
        if returned <= due:
            return 0.0
        days = 0
        current = due + timedelta(days=1)
        while current <= returned:
            if current.weekday() < 5:  # Mon-Fri
                days += 1
            current += timedelta(days=1)
        return days * self.daily_fine
